function identity() { const manifest = JSON.parse(readFileSync(join(ROOT, 'package.json'), 'utf8')); const lock = JSON.parse(readFileSync(join(ROOT, 'package-lock.json'), 'utf8')); const scaffold = JSON.parse(readFileSync(join(ROOT, 'node_modules', '@orkestrel', 'scaffold', 'package.json'), 'utf8')); const test = JSON.parse(readFileSync(join(ROOT, 'node_modules', '@orkestrel', 'test', 'package.json'), 'utf8')); return { manifest: { scaffold: manifest.devDependencies?.['@orkestrel/scaffold'], test: manifest.devDependencies?.['@orkestrel/test'] }, lock: { scaffold: lock.packages?.['node_modules/@orkestrel/scaffold'], test: lock.packages?.['node_modules/@orkestrel/test'] }, installed: { scaffold: scaffold.version, test: test.version } } }
