function requireIdentity(value) { if (value.manifest.scaffold !== '^0.0.75' || value.manifest.test !== '^0.0.18' || value.lock.scaffold?.version !== '0.0.75' || value.lock.test?.version !== '0.0.18' || value.lock.scaffold?.integrity !== INTEGRITY || value.installed.scaffold !== '0.0.75' || value.installed.test !== '0.0.18') throw new Error('Accepted registry identity mismatch') }
export async function execute(commit, run) { if (!/^[a-f0-9]{40}$/.test(commit) || !/^[a-z][a-z0-9-]{0,79}$/.test(run)) throw new Error('Supply a full commit hash and bounded run name'); requireTarget(commit); if (!existsSync(NODE) || !existsSync(NPM)) throw new Error('Node or npm entry is unavailable'); const directory = join(SCRATCH, 'original-install', run); if (existsSync(directory)) throw new Error('Install evidence exists'); mkdirSync(directory, { recursive: true }); const before = { identity: identity(), snapshot: snapshot() }; write(directory, 'before.json', before); try { const stdout = openSync(join(directory, 'npm.stdout.log.txt'), 'wx'); const stderr = openSync(join(directory, 'npm.stderr.log.txt'), 'wx'); const result = await new Promise((resolveExit, rejectExit) => { const child = spawn(NODE, [NPM, 'ci', '--ignore-scripts', '--no-audit', '--no-fund'], { cwd: ROOT, shell: false, windowsHide: true, stdio: ['ignore', stdout, stderr] }); child.once('error', rejectExit); child.once('close', (exit, signal) => resolveExit({ pid: child.pid, exit, signal })) }); closeSync(stdout); closeSync(stderr); write(directory, 'command.json', { executable: NODE, entry: NPM, arguments: ['ci', '--ignore-scripts', '--no-audit', '--no-fund'], result }); const after = { identity: identity(), snapshot: snapshot() }; write(directory, 'after.json', after); if (JSON.stringify(before.snapshot) !== JSON.stringify(after.snapshot)) throw new Error('Original source, index, or manifest snapshot changed'); if (result.exit !== 0 || result.signal !== null) throw new Error('npm ci failed'); requireIdentity(after.identity); write(directory, 'terminal.json', { success: true }); return 0 } catch (error) { write(directory, 'terminal.json', { success: false, message: error instanceof Error ? error.message : String(error) }); return 1 } }
